#include "Generator.h"

#include <charconv>
#include <cstdint>
#include <string>
#include <vector>

namespace Nexyl::Nht {

namespace {

constexpr const char* kHeader =
    "// Generated by Tools.NHT. Do not edit: change the reflected headers or the tool instead (CLAUDE.md, rule 12).\n";

// A C++ string literal. Bytes outside printable ASCII become octal escapes, so the file is pure ASCII.
std::string Literal(const std::string& text) {
    std::string result = "\"";
    for (const char character : text) {
        const auto byte = static_cast<unsigned char>(character);
        if (character == '"' || character == '\\') {
            result += '\\';
            result += character;
        } else if (byte < 0x20U || byte >= 0x7FU) {
            const unsigned value = byte;
            // A backslash, then three octal digits.
            result += '\\';
            result += static_cast<char>('0' + ((value >> 6U) & 7U));
            result += static_cast<char>('0' + ((value >> 3U) & 7U));
            result += static_cast<char>('0' + (value & 7U));
        } else {
            result += character;
        }
    }
    result += '"';
    return result;
}

std::string Hex(std::uint64_t value) {
    char buffer[24] = {};
    const auto end = std::to_chars(buffer, buffer + sizeof(buffer), value, 16).ptr;
    return "0x" + std::string(buffer, end) + "ULL";
}

std::string Integer(std::int64_t value) {
    // The most negative value has no positive literal; spell it as an expression.
    if (value == INT64_MIN) {
        return "(-9223372036854775807LL - 1)";
    }
    return std::to_string(value) + "LL";
}

std::string Double(double value) {
    char buffer[40] = {};
    const auto end = std::to_chars(buffer, buffer + sizeof(buffer), value).ptr;
    std::string text(buffer, end);
    if (text.find_first_of(".eE") == std::string::npos) {
        text += ".0";
    }
    return text;
}

std::string Bool(bool value) {
    return value ? "true" : "false";
}

std::string FieldFlags(const FieldModel& field) {
    std::vector<std::string> flags;
    if (field.isPublic) {
        flags.emplace_back("Public");
    }
    if (field.tags.transient) {
        flags.emplace_back("Transient");
    }
    if (field.tags.presentation) {
        flags.emplace_back("Presentation");
    }
    if (field.tags.readOnly) {
        flags.emplace_back("ReadOnly");
    }
    if (field.tags.hidden) {
        flags.emplace_back("Hidden");
    }
    if (field.tags.noScript) {
        flags.emplace_back("NoScript");
    }
    std::string result = "Flags<FieldFlag>{";
    for (std::size_t index = 0; index < flags.size(); ++index) {
        result += (index == 0 ? "FieldFlag::" : ", FieldFlag::") + flags[index];
    }
    return result + "}";
}

std::string TypeFlags(const Tags& tags) {
    if (tags.hidden && tags.noScript) {
        return "Flags<TypeFlag>{TypeFlag::Hidden, TypeFlag::NoScript}";
    }
    if (tags.hidden) {
        return "Flags<TypeFlag>{TypeFlag::Hidden}";
    }
    if (tags.noScript) {
        return "Flags<TypeFlag>{TypeFlag::NoScript}";
    }
    return "Flags<TypeFlag>{}";
}

std::string Module(const std::string& module) {
    std::string result;
    for (const char character : module) {
        if (character != '.') {
            result += character;
        }
    }
    return result;
}

void WriteRecord(std::string& out, const TypeModel& type, std::size_t index) {
    const std::string cpp = "::" + type.name;
    const std::string number = std::to_string(index);
    std::string fields = "Span<const FieldInfo>()";
    if (!type.fields.empty()) {
        out += "constexpr FieldInfo kFields" + number + "[] = {\n";
        for (const FieldModel& field : type.fields) {
            out += "    MakeField(" + Literal(field.name) + ", " + Hex(field.typeId) + ", " +
                   std::to_string(field.offset) + ", " + FieldFlags(field) + ", " + Literal(field.tags.description) +
                   ", " + Literal(field.tags.units) + ", " + Literal(field.tags.category) + ", " +
                   Literal(field.tags.renamedFrom) + ", " + Bool(field.tags.hasRange) + ", " +
                   Double(field.tags.rangeMinimum) + ", " + Double(field.tags.rangeMaximum) + ", " +
                   Double(field.tags.step) + "),\n";
        }
        out += "};\n";
        fields = "Span<const FieldInfo>(kFields" + number + ")";
    }
    out += "constexpr TypeInfo kType" + number + " = MakeRecordType<" + cpp + ">(" + Literal(type.name) + ", " +
           Hex(type.id) + ", " + TypeFlags(type.tags) + ", " + Literal(type.tags.description) + ", " +
           Literal(type.tags.category) + ", " + Literal(type.tags.renamedFrom) + ", " + Hex(type.baseId) + ", " +
           fields + ");\n";
    for (const FieldModel& field : type.fields) {
        if (!field.isPublic) {
            continue;
        }
        out += "static_assert(TypeIdOf<decltype(" + cpp + "::" + field.name + ")>().value == " + Hex(field.typeId) +
               ", \"Tools.NHT and the compiler disagree on the type of " + type.name + "::" + field.name + ".\");\n";
        if (type.checkOffsets) {
            out += "static_assert(offsetof(" + cpp + ", " + field.name + ") == " + std::to_string(field.offset) +
                   ", \"Tools.NHT and the compiler disagree on the offset of " + type.name + "::" + field.name +
                   ".\");\n";
        }
    }
}

void WriteEnum(std::string& out, const TypeModel& type, std::size_t index) {
    const std::string cpp = "::" + type.name;
    const std::string number = std::to_string(index);
    std::string values = "Span<const EnumValueInfo>()";
    if (!type.values.empty()) {
        out += "constexpr EnumValueInfo kValues" + number + "[] = {\n";
        for (const EnumValueModel& value : type.values) {
            out += "    MakeEnumValue(" + Literal(value.name) + ", " + Integer(value.value) + ", " +
                   Literal(value.tags.description) + ", " + Literal(value.tags.renamedFrom) + ", " +
                   Bool(value.tags.hidden) + "),\n";
        }
        out += "};\n";
        values = "Span<const EnumValueInfo>(kValues" + number + ")";
    }
    out += "constexpr TypeInfo kType" + number + " = MakeEnumType<" + cpp + ">(" + Literal(type.name) + ", " +
           Hex(type.id) + ", " + TypeFlags(type.tags) + ", " + Literal(type.tags.description) + ", " +
           Literal(type.tags.category) + ", " + Literal(type.tags.renamedFrom) + ", " + Hex(type.underlyingId) + ", " +
           values + ");\n";
    for (const EnumValueModel& value : type.values) {
        out += "static_assert(static_cast<i64>(" + cpp + "::" + value.name + ") == " + Integer(value.value) +
               ", \"Tools.NHT and the compiler disagree on the value of " + type.name + "::" + value.name + ".\");\n";
    }
}

} // namespace

std::string TableObjectName(const std::string& module) {
    return "k" + Module(module) + "TypeTable";
}

std::string GenerateTable(const ModuleModel& model) {
    std::string out = kHeader;
    out += "// The reflection table of the module " + model.module + ".\n\n";
    out += "#include <Nexyl/Base/Flags.h>\n";
    out += "#include <Nexyl/Base/Span.h>\n";
    out += "#include <Nexyl/Base/Std/CStdDef.h>\n";
    out += "#include <Nexyl/Base/Types.h>\n";
    out += "#include <Nexyl/Reflection/IntrinsicTypes.h>\n";
    out += "#include <Nexyl/Reflection/TableBuilder.h>\n";
    out += "#include <Nexyl/Reflection/TypeId.h>\n";
    out += "#include <Nexyl/Reflection/TypeInfo.h>\n";
    for (const std::string& header : model.headers) {
        out += "#include " + Literal(header) + "\n";
    }
    out += "\nnamespace Nexyl::Reflection::Generated {\n\nnamespace {\n\n";
    out += "using Detail::MakeEnumType;\nusing Detail::MakeEnumValue;\nusing Detail::MakeField;\n";
    out += "using Detail::MakeOpaqueType;\nusing Detail::MakeRecordType;\n\n";

    for (std::size_t index = 0; index < model.types.size(); ++index) {
        const TypeModel& type = model.types[index];
        const std::string cpp = "::" + type.name;
        out += "// " + type.name + "\n";
        switch (type.shape) {
            case TypeShape::Record:
                WriteRecord(out, type, index);
                break;
            case TypeShape::Enum:
                WriteEnum(out, type, index);
                break;
            case TypeShape::Opaque:
                out += "constexpr TypeInfo kType" + std::to_string(index) + " = MakeOpaqueType<" + cpp + ">(" +
                       Literal(type.name) + ", " + Hex(type.id) + ", " + TypeFlags(type.tags) + ", " +
                       Literal(type.tags.description) + ", " + Literal(type.tags.category) + ", " +
                       Literal(type.tags.renamedFrom) + ");\n";
                break;
        }
        out += "static_assert(TypeIdOf<" + cpp + ">().value == " + Hex(type.id) +
               ", \"Tools.NHT and the compiler disagree on the TypeId of " + type.name + ".\");\n";
        out += "static_assert(sizeof(" + cpp + ") == " + std::to_string(type.size);
        out += " && alignof(" + cpp + ") == " + std::to_string(type.alignment);
        out += ", \"Tools.NHT and the compiler disagree on the layout of " + type.name + ".\");\n\n";
    }

    for (const IntrinsicUse& use : model.intrinsics) {
        out += "static_assert(TypeIdOf<" + use.spelling + ">().value == " + Hex(use.id) +
               ", \"Tools.NHT and the compiler disagree on the TypeId of " + use.spelling + ".\");\n";
    }

    const std::size_t count = model.types.size() + model.intrinsics.size();
    std::string types = "Span<const TypeInfo* const>()";
    if (count > 0) {
        out += "\nconstexpr const TypeInfo* kTypes[] = {\n";
        for (std::size_t index = 0; index < model.types.size(); ++index) {
            out += "    &kType" + std::to_string(index) + ",\n";
        }
        for (const IntrinsicUse& use : model.intrinsics) {
            out += "    &IntrinsicTypeInfo<" + use.spelling + ">(),\n";
        }
        out += "};\n";
        types = "Span<const TypeInfo* const>(kTypes)";
    }
    const std::string table = TableObjectName(model.module);
    out += "\n} // namespace\n\n";
    out += "extern const TypeTable " + table + ";\n";
    out += "constinit const TypeTable " + table + "{" + Literal(model.module) + ", " + types + "};\n";
    out += "\n} // namespace Nexyl::Reflection::Generated\n";
    return out;
}

std::string GenerateAggregate(const std::vector<std::string>& modules) {
    std::string out = kHeader;
    out += "// The reflection tables of the modules below Reflection, compiled into Reflection.\n\n";
    out += "#include <Nexyl/Base/Span.h>\n";
    out += "#include <Nexyl/Reflection/FoundationTypes.h>\n";
    out += "#include <Nexyl/Reflection/TypeInfo.h>\n\n";
    out += "namespace Nexyl::Reflection {\n\n";
    if (!modules.empty()) {
        out += "namespace Generated {\n\n";
        for (const std::string& module : modules) {
            out += "extern const TypeTable " + TableObjectName(module) + ";\n";
        }
        out += "\n} // namespace Generated\n\nnamespace {\n\nconstexpr const TypeTable* kTables[] = {\n";
        for (const std::string& module : modules) {
            out += "    &Generated::" + TableObjectName(module) + ",\n";
        }
        out += "};\n\n} // namespace\n\n";
        out += "Span<const TypeTable* const> GetFoundationTypeTables() {\n";
        out += "    return Span<const TypeTable* const>(kTables);\n}\n";
    } else {
        out += "Span<const TypeTable* const> GetFoundationTypeTables() {\n";
        out += "    return Span<const TypeTable* const>();\n}\n";
    }
    out += "\n} // namespace Nexyl::Reflection\n";
    return out;
}

} // namespace Nexyl::Nht
